// ~4 chars/token is the standard rough approximation for GPT models.
const estTokens = (s) => Math.ceil((String(s || '').length) / 4);

// Fixed instruction overhead of THIS agent's prompt (rules + full glossary + return schema).
// It is baked into the AI Agent node and not readable here, so it is a constant.
// CALIBRATE ONCE: on the first run where OpenAI surfaces real usage, compare and adjust.
const PROMPT_INSTRUCTION_TOKENS = 4200;

return $input.all().map((item, i) => {
  const src = $('Extract Judgment Text').itemMatching(i)?.json ?? {};
  const raw = item.json.output ?? item.json.text ?? '';

  let pack;
  try { pack = JSON.parse(String(raw).replace(/```json|```/g, '').trim()); }
  catch (e) { pack = { extraction_confidence: 'low', extraction_confidence_note: 'parse_error' }; }

  // evidence rule: ungrounded core text fields become "unknown"
  for (const k of ['key_facts','legal_issue','outcome','wider_relevance']) {
    if (!pack[k] || /^\s*$/.test(String(pack[k]))) pack[k] = 'unknown';
  }

  // disposal is a strict enum; the model sometimes appends a citation ("dismissed (¶26)").
  // Extract the first valid enum word from wherever it appears; default to 'other'.
  const d = String(pack.disposal || '').toLowerCase().match(/allowed|dismissed|remitted|other/);
  pack.disposal              = d ? d[0] : 'other';

  // procedural_posture is a strict enum; the model appends citations ("appeal (¶1)").
  // Extract the first valid enum value; default to 'first_instance'.
  const p = String(pack.procedural_posture || '').toLowerCase().match(/first_instance|appeal/);
  pack.procedural_posture    = p ? p[0] : 'first_instance';

  // scalar defaults (never null into the write)
  pack.related_case_uri      = pack.related_case_uri      || null;
  pack.agent_justification   = pack.agent_justification   || 'unknown';
  pack.extraction_confidence = pack.extraction_confidence || 'low';
  pack.extraction_confidence_note = pack.extraction_confidence_note || '';

  // jsonb defaults (never undefined -> never a ::jsonb cast error)
  pack.difficult_terms  = Array.isArray(pack.difficult_terms) ? pack.difficult_terms : [];
  pack.topic_tags       = Array.isArray(pack.topic_tags)      ? pack.topic_tags      : [];
  pack.sensitivity_flags = (pack.sensitivity_flags && typeof pack.sensitivity_flags === 'object')
                           ? pack.sensitivity_flags : { medical:false, minors:false, notes:'' };

  // verbatim quote check against the source body
  const body = src.text || '';
  pack.key_quotes = (Array.isArray(pack.key_quotes) ? pack.key_quotes : [])
    .filter(q => q && q.text && body.includes(String(q.text).trim()));

  // tokens_used: real usage if the agent surfaced it, otherwise estimate.
  const usage = item.json.tokenUsage || item.json.usage ||
                item.json.response?.usage || item.json.llmOutput?.tokenUsage || null;
  let tokens_used = usage?.totalTokens ?? usage?.total_tokens ?? null;

  if (tokens_used == null) {
    const promptTokens = PROMPT_INSTRUCTION_TOKENS
      + estTokens(src.case_name) + estTokens(src.court)
      + estTokens(src.neutral_citation) + estTokens(src.text);
    const completionTokens = estTokens(raw);
    tokens_used = promptTokens + completionTokens;
  }

  return { json: {
    document_uri: src.document_uri,
    case_name: src.case_name,
    ...pack,
    model_version: 'gpt-5-mini',
    prompt_version: 'briefing-2026-07-18-a',
    tokens_used: tokens_used,   // real if available, else estimate
    cost_gbp: null
  }};
});

return $input.all().map((item, i) => {
  const meta = $('Load selected cases').itemMatching(i)?.json ?? {};   // ← set to your B2 node's EXACT name
  const xml  = item.json.xml ?? item.json.data ?? item.json.body ?? item.json.text ?? '';

  const text = String(xml)
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&#8217;/g, '\u2019').replace(/&#8220;/g, '\u201C').replace(/&#8221;/g, '\u201D')
    .replace(/&#8211;/g, '\u2013').replace(/&#8230;/g, '\u2026').replace(/&#160;/g, ' ')
    .replace(/&#169;/g, '\u00A9').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();

  return { json: {
    document_uri: meta.document_uri,
    case_name: meta.case_name,
    court: meta.court,
    xml_url: meta.xml_url,
    html_url: meta.html_url,
    published_at: meta.published_at,
    neutral_citation: meta.neutral_citation,
    text,
    fetch_status: text.length < 500 ? 'thin' : 'ok'
  }};
});

