INSERT INTO human_gate_actions
  (document_uri, gate_type, actor, actor_channel, action_at, selection_decision)
VALUES ($1, 'triage_selection', $2, 'tableau', now(), 'proceed');

INSERT INTO human_gate_actions
  (document_uri, gate_type, actor, actor_channel, action_at, rejection_reason)
VALUES ($1, 'triage_selection', $2, 'form', now(), $3);

UPDATE cases SET case_status = 'rejected', rejection_reason = $2,
  future_relevance_flag = true, updated_at = now()
WHERE document_uri = $1;

