const REASON_CODES = {
  'Outside our configured topics': 'legal_issue_tag',
  'Narrow application — affects few people': 'wider_relevance',
  'Outcome unclear or changes nothing in practice': 'outcome',
  'Facts too thin or technical to explain': 'facts',
  'No usable quotable material': 'key_quotes',
  'Court too low — limited reach': 'court_tier',
  'Procedural or interim only — no substantive decision': 'procedural',
  'Duplicate of a case already selected': 'duplicate',
  'Sensitivity — distressing content or minors': 'sensitivity',
  'Relevant but no capacity this week': 'capacity',
  'Other — see notes': 'other'
};

const j = $json;
const isForm = j.submittedAt !== undefined || j.formMode !== undefined;

if (isForm) {
  const label = String(j['Rejection reason'] || '').trim();
  const notes = String(j['Notes'] || '').trim();
  return [{ json: {
    document_uri:          j.document_uri || null,
    action:                'reject',
    actor:                 j.actor || 'unknown',
    rejection_reason_code: REASON_CODES[label] || 'other',
    rejection_reason:      notes ? `${label} — ${notes}` : label,
    edit_summary:          null
  }}];
}

const q = j.query || {};
const b = j.body  || {};
const r = Object.keys(b).length ? b : q;

return [{ json: {
  document_uri:          r.document_uri || null,
  action:                String(r.action || '').toLowerCase().trim(),
  actor:                 r.actor || 'unknown',
  rejection_reason_code: r.rejection_reason_code || null,
  rejection_reason:      r.rejection_reason || null,
  edit_summary:          r.edit_summary || null
}}];
